/** The event a successful API call stands for, or null when it is only a read. */
export function activityFromApi(method: string | undefined, path: string): ActivityEvent | null {
  const m = (method ?? 'GET').toUpperCase();
  const p = path.split('?')[0].replace(/\/+$/, '') || '/';
  for (const r of RULES) {
    if (r.method === m && r.path.test(p)) return r.event;
  }
  return null;
}

/**
 * A click on a download link, from its href: any anchor the app renders for
 * /api/files/<id>/download. The id itself is dropped.
 */
export function downloadEventFromHref(href: string): ActivityEvent | null {
  let path: string;
  try {
    path = new URL(href, 'https://app.dosya.dev').pathname;
  } catch {
    return null;
  }
  if (/^\/api\/files\/[^/]+\/download$/.test(path)) return { name: 'file_download', params: { kind: 'file' } };
  return null;
}

/**
 * Route segments that identify a thing (file, persona, ticket, share, token)
 * become ":id", so a page_view says "a share analytics page" and not which
 * share. Anything after a known prefix is redacted; unknown routes keep only
 * segments that look like words.
 */
const ID_ROUTES = ['/personas', '/file-requests', '/support', '/shared', '/save', '/editor', '/text-editor', '/family/join', '/s'];

export function sanitizeAppPath(pathname: string): string {
  const clean = pathname.split('?')[0].split('#')[0];
  for (const prefix of ID_ROUTES) {
    if (clean === prefix) return clean;
    if (clean.startsWith(prefix + '/')) return `${prefix}/:id`;
  }
  // A segment with digits or 20+ characters is an identifier of some kind.
  return clean
    .split('/')
    .map((seg) => (seg && (/\d/.test(seg) || seg.length >= 20) ? ':id' : seg))
    .join('/');
}

/** Upload sizes as bands, so a report can say how big things people send without a single exact size leaving the app. */
export function sizeBand(bytes: number): string {
  const MB = 1_048_576;
  if (!Number.isFinite(bytes) || bytes < 0) return 'unknown';
  if (bytes < MB) return 'under_1mb';
  if (bytes < 10 * MB) return '1_10mb';
  if (bytes < 100 * MB) return '10_100mb';
  if (bytes < 1024 * MB) return '100mb_1gb';
  if (bytes < 10 * 1024 * MB) return '1_10gb';
  return 'over_10gb';
}

// ---------------------------------------------------------------------------
// The relay's contract. The mobile and desktop apps have no Google tag: they
// post small batches to the API, which forwards them. The API accepts only
// what cleanRelayEvent() lets through, so a client bug cannot leak a file
// name: an unknown event is dropped, an unknown parameter is dropped, and a
// value that does not look like a category is dropped.
// ---------------------------------------------------------------------------

/** Events an app sends by name, on top of the ones derived from API calls. */
const DIRECT_EVENTS: Array<{ name: string; params: string[] }> = [
  { name: 'page_view', params: ['screen'] },
  { name: 'app_open', params: [] },
  { name: 'sign_up', params: ['method'] },
  { name: 'login', params: ['method'] },
  { name: 'logout', params: [] },
  { name: 'file_upload', params: ['size_band', 'source'] },
  { name: 'file_download', params: ['kind'] },
  { name: 'paywall_view', params: ['source'] },
  { name: 'purchase_complete', params: ['store', 'kind'] },
  { name: 'sync_complete', params: ['result'] },
];

/** Parameters the relay stamps itself; a client may not set them. */
const RELAY_OWNED_PARAMS = ['app_platform', 'app_version', 'app_channel', 'session_id', 'engagement_time_msec', 'timestamp_micros', 'page_location', 'page_title'];

export const RELAY_EVENT_NAMES: ReadonlySet<string> = new Set([
  ...RULES.map((r) => r.event.name),
  ...DIRECT_EVENTS.map((e) => e.name),
]);

export const RELAY_PARAM_KEYS: ReadonlySet<string> = new Set([
  ...RULES.flatMap((r) => Object.keys(r.event.params ?? {})),
  ...DIRECT_EVENTS.flatMap((e) => e.params),
]);

/** A category, a band or a route template: short, and no room for a sentence, an address or a file name with spaces. */
const RELAY_VALUE = /^[A-Za-z0-9_.:/-]{1,64}$/;

/**
 * What the relay will forward of one event, or null when its name is not in
 * the catalogue. Parameters outside the catalogue, the relay's own
 * parameters, and values that are not short category-like strings, finite
 * numbers or booleans are left out rather than refused, so one bad parameter
 * does not lose the event.
 */
export function cleanRelayEvent(name: unknown, params: unknown): ActivityEvent | null {
  if (typeof name !== 'string' || !RELAY_EVENT_NAMES.has(name)) return null;
  const out: Record<string, string | number | boolean> = {};
  if (params && typeof params === 'object' && !Array.isArray(params)) {
    for (const [key, value] of Object.entries(params as Record<string, unknown>)) {
      if (!RELAY_PARAM_KEYS.has(key) || RELAY_OWNED_PARAMS.includes(key)) continue;
      if (typeof value === 'boolean') out[key] = value;
      else if (typeof value === 'number' && Number.isFinite(value)) out[key] = value;
      else if (typeof value === 'string' && RELAY_VALUE.test(value)) out[key] = value;
    }
  }
  return Object.keys(out).length ? { name, params: out } : { name };
}

/**
 * A screen name from a route template, for apps whose router hands out the
 * template itself (expo-router segments such as ["(tabs)", "vault", "space",
 * "[id]"]). Groups in parentheses are not part of the address and are dropped;
 * a dynamic segment becomes ":id". Everything under the Vault is reported as
 * "/vault" and nothing deeper.
 */
export function screenFromSegments(segments: readonly string[]): string {
  const parts: string[] = [];
  for (const seg of segments) {
    if (!seg || (seg.startsWith('(') && seg.endsWith(')'))) continue;
    if (seg.startsWith('[') && seg.endsWith(']')) parts.push(':id');
    else if (/^[a-z0-9_-]{1,40}$/i.test(seg) && !/\d{3,}/.test(seg)) parts.push(seg);
    else parts.push(':id');
  }
  if (parts[0] === 'vault' || parts[0] === 'vault-diagnostics') return '/vault';
  return '/' + parts.join('/');
}
